def max_energy(beads):
    # Flip the beads to facilitate dynamic programming
    n = len(beads)
    flipped_beads = [-1] * n
    for i in range(1, n):
        flipped_beads[i] = flipped_beads[i-1] if beads[i-1] == beads[i] else beads[i]

    # Use dynamic programming to find the maximum energy
    dp = [[0] * (1 << n) for _ in range(n+1)]
    for i in range(n):
        dp[2][1 << i] = flipped_beads[i]

    for bit in range(0, 1 << n):
        for i in range(1, n):
            if bit & (1 << i):
                next_bit = bit ^ (1 << i)
                for j in range(1, i):
                    if bit & (1 << j) and j < i:
                        dp[i + 1][next_bit | (1 << (i-1)) | (1 << j)] = max(dp[i + 1][next_bit | (1 << (i-1)) | (1 << j)], dp[i][j] * flipped_beads[i])

    return dp[n][1 << len(beads) - 1]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    # Handle the case when the polynomial is constant
    if n == 0:
        return str(coeffs[0])

    # Initialize the output string
    result = []

    # Iterate through the coefficients
    for i, coef in enumerate(coeffs[::-1]):
        # Skip terms with coefficient 0
        if coef == 0:
            continue

        # Format the term
        if coef == -1:
            sign = "-"
        elif coef > 0:
            sign = "+"
        else:
            sign = ""

        abs_coef = abs(coef)

        if abs_coef > 1:
            term = f"{abs_coef}x^{n - i}"
        elif abs_coef == 1 and i != 0:
            term = f"x^{n - i}"
        else:
            term = f"x"

        # Combine the term with the sign and append to the result
        result.append(sign + term)
        n -= 1

    # Join the terms with a single space and return
    return ' '.join(result)

def decode(encoded: str, original: str, message: str) -> str:
    # Create a mapping of encoded to original letters
    mapping = {}

    # Construct the mapping if the encoded message and original message have the same length
    if len(encoded) != len(message):
        return "Failed"
    for i in range(len(encoded)):
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        else:
            if mapping[encoded[i]] != original[i]:
                return "Failed"

    # Initialize an empty list to store decoded characters
    decoded_chars = []

    # Decode the message using the constructed mapping
    for char in message:
        if char in mapping:
            decoded_chars.append(mapping[char])
        else:
            return "Failed"

    # Join the decoded characters into a string and return
    return ''.join(decoded_chars)

