from collections import deque

def string_transformation(A, B, rules):
    if len(A) > len(B):
        return "NO ANSWER!"

    transformation_steps = 0
    queue = deque([(A, 0)])
    visited = set()

    while queue:
        current_word, steps = queue.popleft()

        if current_word == B:
            return steps

        for source, target in rules:
            if source in current_word:
                new_word = current_word.replace(source, target)
                if new_word not in visited:
                    visited.add(new_word)
                    queue.append((new_word, steps + 1))

        transformation_steps += 1

        # Early return if the maximum number of steps is reached
        if transformation_steps > 10:
            return "NO ANSWER!"

    return "NO ANSWER!"

