def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    # Sort the areas based on their start coordinates
    areas.sort(key=lambda x: x[0])

    remaining_trees = l
    current_end = 0

    # Iterate through each area and update the remaining trees accordingly
    for start, end in areas:
        if current_end < start:
            remaining_trees -= (end - current_end)
            current_end = end
        elif end > current_end:
            remaining_trees -= (end - current_end)

    return remaining_trees

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    """Calculate the maximum total value of herbs that can be picked within a given time limit."""
    dp = [[0] * (T + 1) for _ in range(M)]

    for i in range(M):
        herb_time, herb_value = herbs[i]
        for time in range(T, herb_time - 1, -1):
            dp[i][time] = max(dp[i][time], herb_value + dp[i - 1][time - herb_time])

    return max(dp[-1])

