def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [0] * (V + 1)

    for i in range(1, n + 1):
        volume = volumes[i - 1]
        for w in range(V, volume - 1, -1):
            dp[w] = max(dp[w], dp[w - volume] + volume)

    max_occupied_volume = dp[V]
    remaining_space = V - max_occupied_volume
    return remaining_space

