def min_groups(w, n, prices):
    def can_fill_group(index, covered_price):
        # Check if the current unicorn and the group have enough to fill their maximum
        if index == n or covered_price >= w:
            # If all unicorns or the total covered price is enough, return true
            return True
        # Otherwise, try both picking the current unicorn or skipping it
        return can_fill_group(index + 1, covered_price + prices[index]) or can_fill_group(index + 1, covered_price)

    def count_groups(n):
        # Initialize the count of groups to 0
        cnt = 0
        # Try picking the first unicorn for each group of 2
        for i in range(0, n, 2):
            if can_fill_group(i, 0):
                cnt += 1
        return cnt

    # Call the helper function to find the minimum number of groups
    return count_groups(n)

